    cols = tl.arange(0, BLOCK_N)

    offs = rows[:, None] * N + cols[None, :]
    mask = (rows[:, None] < M) & (cols[None, :] < N)

    dy = tl.load(DY + offs, mask=mask, other=0.0).to(tl.float32)
    xhat = tl.load(XHAT + offs, mask=mask, other=0.0).to(tl.float32)
    w = tl.load(W + cols, mask=cols < N, other=0.0).to(tl.float32)
    rstd = tl.load(RSTD + rows, mask=rows < M, other=0.0).to(tl.float32)

    dy = tl.where(mask, dy, 0.0)
    xhat = tl.where(mask, xhat, 0.0)

    g = dy * w[None, :]
    g = tl.where(mask, g, 0.0)

    sum_g = tl.sum(g, axis=1)
    sum_g_xhat = tl.sum(g * xhat, axis=1)

    mean_g = sum_g[:, None] / N
    mean_g_xhat = sum_g_xhat[:, None] / N

    dx = rstd[:, None] * (g - mean_g - xhat * mean_g_xhat)
